INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_aj-7-present-perfect_0','Jak tvoříme present perfect?',ARRAY['did + infinitiv','will + infinitiv','was/were + sloveso -ing','have/has + 3. tvar slovesa']::TEXT[],3,'She has played.',1,ARRAY[]::TEXT[],NULL,0,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_1','Doplň: I … seen that film.',ARRAY['am','have','had','has']::TEXT[],1,'S I se používá have.',1,ARRAY[]::TEXT[],NULL,1,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_2','Doplň: She … finished her homework.',ARRAY['have','has','is','had']::TEXT[],1,'S she se používá has.',1,ARRAY[]::TEXT[],NULL,2,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_3','Jaký je 3. tvar slovesa go?',ARRAY['goed','went','gone','going']::TEXT[],2,'go – went – gone.',2,ARRAY[]::TEXT[],NULL,3,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_4','Jaký je 3. tvar slovesa eat?',ARRAY['ate','eated','eaten','eating']::TEXT[],2,'eat – ate – eaten.',2,ARRAY[]::TEXT[],NULL,4,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_5','Doplň: We … never been to London.',ARRAY['did','has','have','are']::TEXT[],2,'We have never been.',2,ARRAY[]::TEXT[],NULL,5,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_6','Doplň: I have lived here … 2020.',ARRAY['from','during','since','for']::TEXT[],2,'Since se používá s časovým bodem.',3,ARRAY[]::TEXT[],NULL,6,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_7','Doplň: I have lived here … five years.',ARRAY['ago','from','since','for']::TEXT[],3,'For se používá s délkou trvání.',3,ARRAY[]::TEXT[],NULL,7,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_8','Jak se zeptáme: Byl jsi někdy v Paříži?',ARRAY['Have you ever went to Paris?','Have you ever been to Paris?','Are you ever been to Paris?','Did you ever be to Paris?']::TEXT[],1,'Have you ever + 3. tvar.',3,ARRAY[]::TEXT[],NULL,8,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_9','Doplň: He hasn''t called me ….',ARRAY['ever','yet','since','already']::TEXT[],1,'Yet se používá v záporu a otázce.',4,ARRAY[]::TEXT[],NULL,9,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_10','Doplň: I have … eaten lunch. (už)',ARRAY['already','yet','never','ever']::TEXT[],0,'Already = už.',4,ARRAY[]::TEXT[],NULL,10,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_11','Která věta je správně?',ARRAY['She has lost her keys.','She has lose her keys.','She has losted her keys.','She have lost her keys.']::TEXT[],0,'Lose – lost – lost.',4,ARRAY[]::TEXT[],NULL,11,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_12','Která z vět je správná?',ARRAY['I saw him yesterday.','I did saw him yesterday.','I have saw him yesterday.','I have seen him yesterday.']::TEXT[],0,'S yesterday používáme past simple.',5,ARRAY[]::TEXT[],NULL,12,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_13','Co znamená věta: I have lost my phone.',ARRAY['Ztratil jsem telefon (a stále ho nemám).','Ztrácel jsem telefon.','Budu ztrácet telefon.','Ztratil jsem telefon minulý týden.']::TEXT[],0,'Present perfect spojuje minulost s přítomností.',5,ARRAY[]::TEXT[],NULL,13,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_14','Vyber správnou větu.',ARRAY['How long do you know her?','How long have you known her?','How long are you knowing her?','How long did you have known her?']::TEXT[],1,'How long + present perfect pro trvající stav.',5,ARRAY[]::TEXT[],NULL,14,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-past-simple-continuous_0','Jaký je minulý čas slovesa play?',ARRAY['plaied','played','playd','plays']::TEXT[],1,'Pravidelná slovesa mají -ed.',1,ARRAY[]::TEXT[],NULL,0,'c_aj-7-past-simple-continuous',NULL,NOW()),
('q_aj-7-past-simple-continuous_1','Jaký je minulý čas slovesa go?',ARRAY['gone','went','goed','going']::TEXT[],1,'Nepravidelné sloveso.',1,ARRAY[]::TEXT[],NULL,1,'c_aj-7-past-simple-continuous',NULL,NOW()),
('q_aj-7-past-simple-continuous_2','Jaký je minulý čas slovesa see?',ARRAY['seeing','saw','seen','seed']::TEXT[],1,'see – saw – seen.',1,ARRAY[]::TEXT[],NULL,2,'c_aj-7-past-simple-continuous',NULL,NOW()),
('q_aj-7-past-simple-continuous_3','Doplň: I … TV when you called.',ARRAY['was watching','have watched','am watching','watched']::TEXT[],0,'Past continuous = činnost v průběhu.',2,ARRAY[]::TEXT[],NULL,3,'c_aj-7-past-simple-continuous',NULL,NOW()),
('q_aj-7-past-simple-continuous_4','Jak tvoříme past continuous?',ARRAY['have + 3. tvar','was/were + sloveso -ing','had + 3. tvar','will + infinitiv']::TEXT[],1,'She was reading.',2,ARRAY[]::TEXT[],NULL,4,'c_aj-7-past-simple-continuous',NULL,NOW()),
('q_aj-7-past-simple-continuous_5','Doplň: They … football when it started to rain.',ARRAY['were playing','was playing','played','are playing']::TEXT[],0,'They → were.',2,ARRAY[]::TEXT[],NULL,5,'c_aj-7-past-simple-continuous',NULL,NOW()),
('q_aj-7-past-simple-continuous_6','Která věta je správně?',ARRAY['I didn''t see him.','I didn''t seen him.','I didn''t saw him.','I not saw him.']::TEXT[],0,'Po didn''t následuje základní tvar.',3,ARRAY[]::TEXT[],NULL,6,'c_aj-7-past-simple-continuous',NULL,NOW()),
('q_aj-7-past-simple-continuous_7','Jak se zeptáme: Šel jsi včera do školy?',ARRAY['Were you go to school yesterday?','Did you go to school yesterday?','Did you went to school yesterday?','Do you went to school yesterday?']::TEXT[],1,'Did + základní tvar.',3,ARRAY[]::TEXT[],NULL,7,'c_aj-7-past-simple-continuous',NULL,NOW()),
('q_aj-7-past-simple-continuous_8','Doplň: While she …, he was cooking.',ARRAY['reads','is reading','read','was reading']::TEXT[],3,'While se používá s past continuous.',3,ARRAY[]::TEXT[],NULL,8,'c_aj-7-past-simple-continuous',NULL,NOW()),
('q_aj-7-past-simple-continuous_9','Doplň: When I arrived, they … dinner.',ARRAY['have','are having','had','were having']::TEXT[],3,'Průběh v okamžik příchodu.',4,ARRAY[]::TEXT[],NULL,9,'c_aj-7-past-simple-continuous',NULL,NOW()),
('q_aj-7-past-simple-continuous_10','Doplň: I … my keys when I was walking home.',ARRAY['was losing','lose','have lost','lost']::TEXT[],3,'Krátká přerušující událost.',4,ARRAY[]::TEXT[],NULL,10,'c_aj-7-past-simple-continuous',NULL,NOW()),
('q_aj-7-past-simple-continuous_11','Které sloveso má jiný minulý čas?',ARRAY['play – played','work – worked','buy – bought','watch – watched']::TEXT[],2,'Buy je nepravidelné.',4,ARRAY[]::TEXT[],NULL,11,'c_aj-7-past-simple-continuous',NULL,NOW()),
('q_aj-7-past-simple-continuous_12','Která z vět je správná?',ARRAY['He is sleeping when the phone rang.','He slept when the phone was ringing.','He was sleeping when the phone was ring.','He was sleeping when the phone rang.']::TEXT[],3,'Dlouhý děj + přerušení.',5,ARRAY[]::TEXT[],NULL,12,'c_aj-7-past-simple-continuous',NULL,NOW()),
('q_aj-7-past-simple-continuous_13','Doplň: What … you doing at 8 o''clock last night?',ARRAY['were','did','are','was']::TEXT[],0,'You → were.',5,ARRAY[]::TEXT[],NULL,13,'c_aj-7-past-simple-continuous',NULL,NOW()),
('q_aj-7-past-simple-continuous_14','Jaký je rozdíl mezi ''I read a book'' a ''I was reading a book''?',ARRAY['žádný','první = dokončeno, druhé = probíhalo','první = budoucnost','první = probíhalo, druhé = dokončeno']::TEXT[],1,'Past simple × past continuous.',5,ARRAY[]::TEXT[],NULL,14,'c_aj-7-past-simple-continuous',NULL,NOW()),
